* {
  box-sizing: border-box;
}

[hidden] {
  display: none !important;
}

body {
  margin: 0;
  font-family: system-ui, -apple-system, "Segoe UI", sans-serif;
  background: #f5f6f8;
  color: #222;
}

header {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 2rem;
  padding: 0.75rem 1.5rem;
  background: #2d4a6b;
  color: #fff;
}

header h1 {
  margin: 0;
  font-size: 1.3rem;
}

nav a {
  margin-right: 1rem;
  padding-bottom: 2px;
  color: #cfe0f5;
  text-decoration: none;
}

nav a.active {
  color: #fff;
  border-bottom: 2px solid #fff;
}

main {
  max-width: 960px;
  margin: 0 auto;
  padding: 1.5rem;
}

.panel {
  display: flex;
  flex-wrap: wrap;
  align-items: flex-end;
  gap: 0.75rem;
  margin-bottom: 1rem;
  padding: 1rem;
  background: #fff;
  border-radius: 6px;
  box-shadow: 0 1px 2px rgba(0, 0, 0, 0.08);
}

label {
  display: flex;
  flex-direction: column;
  gap: 0.25rem;
  font-size: 0.85rem;
}

input,
select,
button {
  padding: 0.4rem 0.5rem;
  font: inherit;
  border: 1px solid #bbb;
  border-radius: 4px;
}

button {
  background: #2d4a6b;
  color: #fff;
  border: none;
  cursor: pointer;
}

button:disabled {
  background: #aab;
  cursor: default;
}

button.delete,
button.delete-budget {
  background: #b03a3a;
}

.toolbar p {
  margin: 0;
  font-weight: 600;
}

#message {
  width: 100%;
  margin: 0;
  color: #b03a3a;
}

table {
  width: 100%;
  margin-bottom: 1rem;
  border-collapse: collapse;
  background: #fff;
}

th,
td {
  padding: 0.5rem;
  text-align: left;
  border-bottom: 1px solid #e3e6ea;
}

th.sortable {
  cursor: pointer;
  user-select: none;
}

tr.over {
  background: #fbe3e3;
  color: #8a1c1c;
  font-weight: 600;
}

canvas {
  max-width: 100%;
  background: #fff;
  border-radius: 6px;
}

