assert(eq(m.map(x => x.date), ['2026-01-31', '2026-02-28', '2026-03-31', '2026-04-30']), 'monthly clamp');
assert(!('every' in m[0]), 'every removed');
const w = expandRecurring({ date: '2026-01-01', description: 'x', amount: 1, category: 'c', every: 'week' }, '2026-01-22');
assert(eq(w.map(x => x.date), ['2026-01-01', '2026-01-08', '2026-01-15', '2026-01-22']), 'weekly inclusive');

const b = checkBudgets(items, [{ category: 'food', limit: 200 }, { category: 'pay', limit: 5000 }], '2026-01');
assert(eq(b, [{ category: 'food', limit: 200, spent: 300, over: true }, { category: 'pay', limit: 5000, spent: 0, over: false }]), 'budgets');

const h = createHistory(0);
h.push(1); h.push(2); h.undo();
assert(h.state() === 1 && h.canRedo(), 'undo');
h.push(3);
assert(!h.canRedo() && h.state() === 3, 'push drops redo');
const h2 = createHistory(0);
for (let i = 1; i <= 60; i++) h2.push(i);
let n = 0; while (h2.canUndo()) { h2.undo(); n++; }
assert(n === 50 && h2.state() === 10, 'max 50 undo steps');
